from fractions import Fraction

n = int(input())
for i in range(n):
    f1 = int(input())
    r1 = int(input())
    f2 = int(input())
    r2 = int(input())
    if r1 != r2:
        g = Fraction(f2 - f1, r1 - r2)
        print(f"equal at {g} units, cost {f1 + r1 * g}")
    elif f1 == f2:
        print("always equal")
    elif f1 < f2:
        print(f"never equal, plan 1 is cheaper by {f2 - f1}")
    else:
        print(f"never equal, plan 2 is cheaper by {f1 - f2}")
